using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace ResearchAgent;

/// <summary>
/// Provides web search capability by querying a search engine and returning results.
/// </summary>
public sealed partial class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [Description("Search the web for information on a given query. Returns a list of relevant results with titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-5)")] int maxResults = 3,
        CancellationToken cancellationToken = default)
    {
        maxResults = Math.Clamp(maxResults, 1, 5);

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);
            var results = ParseSearchResults(html, maxResults);

            if (results.Count == 0)
            {
                return $"No results found for: {query}";
            }

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"");
            sb.AppendLine();

            for (var i = 0; i < results.Count; i++)
            {
                var (title, snippet, resultUrl) = results[i];
                sb.AppendLine($"{i + 1}. **{title}**");
                if (!string.IsNullOrEmpty(resultUrl))
                {
                    sb.AppendLine($"   URL: {resultUrl}");
                }
                sb.AppendLine($"   {snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    [Description("Fetch and read the content of a specific web page URL. Returns the text content of the page.")]
    public async Task<string> ReadWebPageAsync(
        [Description("The URL of the web page to read")] string url,
        [Description("Maximum number of characters to return")] int maxLength = 3000,
        CancellationToken cancellationToken = default)
    {
        maxLength = Math.Clamp(maxLength, 500, 5000);

        try
        {
            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);
            var text = StripHtmlTags(html);

            if (text.Length > maxLength)
            {
                text = text[..maxLength] + "\n... [truncated]";
            }

            return $"Content from {url}:\n\n{text}";
        }
        catch (HttpRequestException ex)
        {
            return $"Failed to read {url}: {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet, string Url)> ParseSearchResults(string html, int maxResults)
    {
        var results = new List<(string Title, string Snippet, string Url)>();

        // Parse DuckDuckGo lite results: links in <a> tags followed by snippet text
        var linkPattern = LinkRegex();
        var matches = linkPattern.Matches(html);

        foreach (Match match in matches)
        {
            if (results.Count >= maxResults)
            {
                break;
            }

            var resultUrl = match.Groups[1].Value;
            var title = StripHtmlTags(match.Groups[2].Value).Trim();

            if (string.IsNullOrEmpty(title) || resultUrl.Contains("duckduckgo.com"))
            {
                continue;
            }

            // Extract snippet: text following the link
            var afterLink = html[(match.Index + match.Length)..];
            var snippet = StripHtmlTags(afterLink);
            snippet = CollapseWhitespace(snippet);
            if (snippet.Length > 200)
            {
                snippet = snippet[..200] + "...";
            }

            results.Add((title, snippet, resultUrl));
        }

        return results;
    }

    private static string StripHtmlTags(string html)
    {
        var text = HtmlTagRegex().Replace(html, " ");
        text = WebUtility.HtmlDecode(text);
        return CollapseWhitespace(text);
    }

    private static string CollapseWhitespace(string text)
    {
        return WhitespaceRegex().Replace(text, " ").Trim();
    }

    [GeneratedRegex("""<a[^>]+href="([^"]+)"[^>]*>(.*?)</a>""", RegexOptions.IgnoreCase | RegexOptions.Singleline)]
    private static partial Regex LinkRegex();

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex HtmlTagRegex();

    [GeneratedRegex(@"\s+")]
    private static partial Regex WhitespaceRegex();
}

/// <summary>
/// Provides note-taking capability for the agent to record and organize research findings.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];

    [Description("Save a research note with a topic tag and content. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("A short topic tag for categorizing the note (e.g., 'definition', 'history', 'key-finding')")] string topic,
        [Description("The content of the note to save")] string content)
    {
        var note = new Note(topic, content, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note #{_notes.Count} saved under topic '{topic}'.";
    }

    [Description("Retrieve all saved research notes, optionally filtered by topic tag.")]
    public string GetNotes(
        [Description("Optional topic filter. Leave empty to get all notes.")] string? topic = null)
    {
        var filtered = string.IsNullOrEmpty(topic)
            ? _notes
            : _notes.Where(n => n.Topic.Contains(topic, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return topic is null
                ? "No notes saved yet."
                : $"No notes found for topic '{topic}'.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"Research Notes ({filtered.Count} total):");
        sb.AppendLine(new string('-', 40));

        for (var i = 0; i < filtered.Count; i++)
        {
            var note = filtered[i];
            sb.AppendLine($"[{note.Topic}] ({note.SavedAt:HH:mm:ss UTC})");
            sb.AppendLine(note.Content);
            sb.AppendLine();
        }

        return sb.ToString();
    }

    [Description("Get a count of all saved notes, grouped by topic.")]
    public string GetNoteSummary()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var groups = _notes.GroupBy(n => n.Topic, StringComparer.OrdinalIgnoreCase);
        var sb = new StringBuilder();
        sb.AppendLine($"Note Summary: {_notes.Count} total notes");

        foreach (var group in groups)
        {
            sb.AppendLine($"  - {group.Key}: {group.Count()} note(s)");
        }

        return sb.ToString();
    }

    private sealed record Note(string Topic, string Content, DateTime SavedAt);
}

