 using System.Reflection;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using OpenAI;
 using ResearchAgent;

 // Configure the LLM provider
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 // Build the IChatClient through the MEAI abstraction
 IChatClient chatClient = new OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 // Create tool instances
 using var httpClient = new HttpClient();
 var webSearch = new WebSearchTool(httpClient);
 var noteTaking = new NoteTakingTool();

 // Create AI tools from instance methods using AIFunctionFactory
 var tools = new List<AITool>();

 foreach (var method in typeof(WebSearchTool).GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
 {
     tools.Add(AIFunctionFactory.Create(method, webSearch));
 }

 foreach (var method in typeof(NoteTakingTool).GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
 {
     tools.Add(AIFunctionFactory.Create(method, noteTaking));
 }

 // Build the research agent with instructions and tools
 const string instructions = """
     You are a research agent. Your job is to research a topic thoroughly using the available tools.

     Follow this process:
     1. Search the web for the topic to find relevant information.
     2. Read promising web pages to gather detailed content.
     3. Save important findings as notes using the note-taking tool, tagging each with a relevant topic.
     4. After gathering enough information (at least 3-5 key findings), retrieve all your notes.
     5. Synthesize everything into a well-structured summary with sections, key facts, and sources.

     Be thorough but concise. Always cite your sources. If a search or page read fails, try
     alternative queries. Focus on factual, well-sourced information.
     """;

 var agent = new ChatClientAgent(
     chatClient,
     instructions,
     name: "ResearchAgent",
     description: "An AI agent that researches topics by searching the web and taking notes.",
     tools: tools);

 // Get the research topic
 Console.ForegroundColor = ConsoleColor.Cyan;
 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║         AI Research Agent                ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.ResetColor();
 Console.WriteLine();

 string topic;
 if (args.Length > 0)
 {
     topic = string.Join(' ', args);
     Console.WriteLine($"Research topic: {topic}");
 }
 else
 {
     Console.Write("Enter a topic to research: ");
     topic = Console.ReadLine()?.Trim() ?? "artificial intelligence";
 }

 Console.WriteLine();
 Console.ForegroundColor = ConsoleColor.Yellow;
 Console.WriteLine($"Researching: \"{topic}\"...");
 Console.ResetColor();
 Console.WriteLine();

 // Run the agent with iteration limits for safety
 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 4096,
 });

 var response = await agent.RunAsync(
     $"Research the following topic and provide a comprehensive summary: {topic}",
     options: runOptions);

 // Display the final response
 Console.ForegroundColor = ConsoleColor.Green;
 Console.WriteLine("═══════════════════════════════════════════");
 Console.WriteLine("  Research Summary");
 Console.WriteLine("═══════════════════════════════════════════");
 Console.ResetColor();
 Console.WriteLine();

 foreach (var message in response.Messages)
 {
     if (message.Role == ChatRole.Assistant && message.Text is { } text)
     {
         Console.WriteLine(text);
     }
 }

 Console.WriteLine();
 Console.ForegroundColor = ConsoleColor.DarkGray;
 Console.WriteLine($"[Agent completed — Usage: {response.Usage?.InputTokenCount ?? 0} input, {response.Usage?.OutputTokenCount ?? 0} output tokens]");
 Console.ResetColor();

